public struct Person {
    public private(set) var courses: [Course] = []   // readable outside, writable inside

    public mutating func addCourse(_ course: Course) throws {
        guard course.isAccepted else { throw CourseError.notAccepted }
        courses.append(course)
    }

    public mutating func removeCourse(_ course: Course) {
        courses.removeAll { $0 == course }
    }
}
